/**
 * Database schema. Column names are camelCase here and snake_case in Postgres
 * (`casing: 'snake_case'`). Ids are UUIDs, mostly generated by clients.
 */
import { sql } from 'drizzle-orm';
import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  real,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import type {
  ActivityField,
  Ingredient,
  Nutrients,
  Profile,
  Serving,
  WorkoutExercise,
} from '@vigortally/schema';

const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

// ---- identity -----------------------------------------------------------------

export const households = pgTable('households', {
  id: uuid().primaryKey(),
  name: text().notNull(),
  createdAt: createdAt(),
});

export const roleEnum = pgEnum('role', ['admin', 'member']);

export const users = pgTable(
  'users',
  {
    id: uuid().primaryKey(),
    householdId: uuid()
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    name: text().notNull(),
    email: text().notNull(),
    passwordHash: text().notNull(),
    role: roleEnum().notNull().default('member'),
    profile: jsonb()
      .$type<Profile>()
      .notNull()
      .default(sql`'{}'::jsonb`),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('users_email_unique').on(sql`lower(${t.email})`)],
);

export const sessionKindEnum = pgEnum('session_kind', ['web', 'device']);

/** Login sessions. Web sessions use a cookie; paired devices send a Bearer token. */
export const sessions = pgTable(
  'sessions',
  {
    id: uuid().primaryKey(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** SHA-256 of the token; the token itself is never stored. */
    tokenHash: text().notNull(),
    kind: sessionKindEnum().notNull(),
    /** Device name for paired apps ("Pixel 9"), user agent summary for web. */
    name: text().notNull().default(''),
    createdAt: createdAt(),
    lastUsedAt: timestamp({ withTimezone: true }),
    /** Web sessions expire; device tokens last until revoked. */
    expiresAt: timestamp({ withTimezone: true }),
  },
  (t) => [uniqueIndex('sessions_token_hash_unique').on(t.tokenHash)],
);

// ---- activities ------------------------------------------------------------------

export const activityKindEnum = pgEnum('activity_kind', ['strength', 'session']);

const ownedBy = () =>
  uuid()
    .notNull()
    .references(() => users.id, { onDelete: 'cascade' });

export const activityTypes = pgTable(
  'activity_types',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    name: text().notNull(),
    kind: activityKindEnum().notNull(),
    presetKey: text(),
    icon: text().notNull().default('activity'),
    fields: jsonb()
      .$type<ActivityField[]>()
      .notNull()
      .default(sql`'[]'::jsonb`),
    archived: boolean().notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index('activity_types_user_idx').on(t.userId)],
);

export const activitySessions = pgTable(
  'activity_sessions',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    activityTypeId: uuid()
      .notNull()
      .references(() => activityTypes.id, { onDelete: 'cascade' }),
    startedAt: timestamp({ withTimezone: true }).notNull(),
    durationSec: integer(),
    values: jsonb()
      .$type<Record<string, number | string>>()
      .notNull()
      .default(sql`'{}'::jsonb`),
    notes: text().notNull().default(''),
    /** `manual`, or the integration that imported it. */
    source: text().notNull().default('manual'),
    externalId: text(),
    createdAt: createdAt(),
  },
  (t) => [index('activity_sessions_user_started_idx').on(t.userId, t.startedAt)],
);

/** User-defined exercises. Built-in ones live in @vigortally/core and are not stored. */
export const exercises = pgTable(
  'exercises',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    name: text().notNull(),
    equipment: text().notNull(),
    muscle: text().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('exercises_user_idx').on(t.userId)],
);

export const workoutTemplates = pgTable(
  'workout_templates',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    name: text().notNull(),
    notes: text().notNull().default(''),
    exercises: jsonb().$type<WorkoutExercise[]>().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('workout_templates_user_idx').on(t.userId)],
);

export const workouts = pgTable(
  'workouts',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    templateId: uuid().references(() => workoutTemplates.id, { onDelete: 'set null' }),
    name: text().notNull(),
    startedAt: timestamp({ withTimezone: true }).notNull(),
    finishedAt: timestamp({ withTimezone: true }),
    notes: text().notNull().default(''),
    /** Exercises and sets as logged. */
    exercises: jsonb().$type<WorkoutExercise[]>().notNull(),
    /** Total weight moved over working sets, kept for quick stats. */
    volumeKg: real().notNull().default(0),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index('workouts_user_started_idx').on(t.userId, t.startedAt)],
);

// ---- nutrition -----------------------------------------------------------------------

export const mealEnum = pgEnum('meal', ['breakfast', 'lunch', 'dinner', 'snack']);

/** Foods are shared within a household. Barcode lookups are cached here too. */
export const foods = pgTable(
  'foods',
  {
    id: uuid().primaryKey(),
    householdId: uuid()
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    createdBy: uuid().references(() => users.id, { onDelete: 'set null' }),
    name: text().notNull(),
    brand: text(),
    barcode: text(),
    source: text().notNull().default('custom'),
    per100g: jsonb().$type<Nutrients>().notNull(),
    servings: jsonb()
      .$type<Serving[]>()
      .notNull()
      .default(sql`'[]'::jsonb`),
    createdAt: createdAt(),
  },
  (t) => [
    index('foods_household_idx').on(t.householdId),
    uniqueIndex('foods_household_barcode_unique').on(t.householdId, t.barcode),
  ],
);

export const diaryEntries = pgTable(
  'diary_entries',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    date: date({ mode: 'string' }).notNull(),
    meal: mealEnum().notNull(),
    foodId: uuid().references(() => foods.id, { onDelete: 'set null' }),
    /** Recipe the entry came from (snapshot kept even if the recipe is deleted). */
    recipeId: uuid(),
    name: text().notNull(),
    grams: real(),
    servings: real(),
    /** Nutrients at the time of logging, so editing a food never rewrites history. */
    nutrients: jsonb().$type<Nutrients>().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('diary_entries_user_date_idx').on(t.userId, t.date)],
);

export const waterEntries = pgTable(
  'water_entries',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    date: date({ mode: 'string' }).notNull(),
    ml: integer().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('water_entries_user_date_idx').on(t.userId, t.date)],
);

/** One weigh-in per user and day. */
export const weighIns = pgTable(
  'weigh_ins',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    date: date({ mode: 'string' }).notNull(),
    weightKg: real().notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('weigh_ins_user_date_unique').on(t.userId, t.date)],
);

// ---- kitchen ----------------------------------------------------------------------------

const householdOwned = () =>
  uuid()
    .notNull()
    .references(() => households.id, { onDelete: 'cascade' });

export const recipes = pgTable(
  'recipes',
  {
    id: uuid().primaryKey(),
    householdId: householdOwned(),
    createdBy: uuid().references(() => users.id, { onDelete: 'set null' }),
    name: text().notNull(),
    servings: real().notNull(),
    ingredients: jsonb().$type<Ingredient[]>().notNull(),
    instructions: text().notNull().default(''),
    tags: jsonb()
      .$type<string[]>()
      .notNull()
      .default(sql`'[]'::jsonb`),
    sourceUrl: text(),
    createdAt: createdAt(),
    updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index('recipes_household_idx').on(t.householdId)],
);

/** Recipes scheduled on a day. Shared by the household. */
export const mealPlanEntries = pgTable(
  'meal_plan_entries',
  {
    id: uuid().primaryKey(),
    householdId: householdOwned(),
    date: date({ mode: 'string' }).notNull(),
    meal: mealEnum().notNull(),
    recipeId: uuid()
      .notNull()
      .references(() => recipes.id, { onDelete: 'cascade' }),
    servings: real().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('meal_plan_household_date_idx').on(t.householdId, t.date)],
);

/** Items ticked off the shopping list. Together with the diary they give assumed stock. */
export const purchases = pgTable(
  'purchases',
  {
    id: uuid().primaryKey(),
    householdId: householdOwned(),
    foodId: uuid()
      .notNull()
      .references(() => foods.id, { onDelete: 'cascade' }),
    grams: real().notNull(),
    purchasedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index('purchases_household_idx').on(t.householdId)],
);

/** Hand-written shopping list items that aren't part of any recipe. */
export const shoppingExtras = pgTable(
  'shopping_extras',
  {
    id: uuid().primaryKey(),
    householdId: householdOwned(),
    text: text().notNull(),
    done: boolean().notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index('shopping_extras_household_idx').on(t.householdId)],
);

// ---- statistics --------------------------------------------------------------------------

/** Widgets on a user's statistics dashboard, in display order. */
export const dashboardWidgets = pgTable(
  'dashboard_widgets',
  {
    id: uuid().primaryKey(),
    userId: ownedBy(),
    position: integer().notNull(),
    title: text().notNull(),
    metric: text().notNull(),
    chart: text().notNull(),
    rangeDays: integer().notNull(),
    bucket: text().notNull(),
    exerciseId: uuid(),
    activityTypeId: uuid(),
  },
  (t) => [index('dashboard_widgets_user_idx').on(t.userId, t.position)],
);

// ---- device pairing ------------------------------------------------------------------------

/** One-time codes shown as a QR code in the web app; the companion app redeems them. */
export const pairingCodes = pgTable('pairing_codes', {
  /** SHA-256 of the code. */
  codeHash: text().primaryKey(),
  userId: ownedBy(),
  expiresAt: timestamp({ withTimezone: true }).notNull(),
  usedAt: timestamp({ withTimezone: true }),
  createdAt: createdAt(),
});
